UPDATE clients c
SET
  phone              = CASE WHEN (c.phone IS NULL OR c.phone = '') AND hs.phone != '' THEN hs.phone ELSE c.phone END,
  hubspot_contact_id = hs.hs_contact_id,
  updated_at         = now()
FROM hs
WHERE LOWER(TRIM(c.email)) = hs.email
  AND c.email IS NOT NULL
  AND c.email != '';
